sPreviewPseudoWidget\n} from '@/core/graph/subgraph/promotionUtils'\nimport { resolveConcretePromotedWidget } from '@/core/graph/subgraph/resolveConcretePromotedWidget'\nimport { resolveSubgraphInputTarget } from '@/core/graph/subgraph/resolveSubgraphInputTarget'\nimport type { SerializedProxyWidgetTuple } from '@/core/schemas/promotionSchema'\nimport { parseProxyWidgets } from '@/core/schemas/promotionSchema'\nimport type {\n  ProxyWidgetErrorQuarantineEntry,\n  ProxyWidgetQuarantineReason\n} from '@/core/schemas/proxyWidgetQuarantineSchema'\nimport { parseProxyWidgetErrorQuarantine } from '@/core/schemas/proxyWidgetQuarantineSchema'\nimport type { INodeInputSlot } from '@/lib/litegraph/src/types/slots'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { nextUniqueName } from '@/lib/litegraph/src/strings'\nimport type { Subgraph } from '@/lib/litegraph/src/subgraph/Subgraph'\nimport type { SubgraphInput } from '@/lib/litegraph/src/subgraph/SubgraphInput'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type {\n  IBaseWidget,\n  TWidgetValue\n} from '@/lib/litegraph/src/types/widgets'\nimport { isWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport {\n  getPreviewExposureHostLocator,\n  usePreviewExposureStore\n} from '@/stores/previewExposureStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport type { LinkTopology } from '@/types/linkTopology'\nimport { toNodeId } from '@/types/nodeId'\nimport type { NodeId, SerializedNodeId } from '@/types/nodeId'\n\ninterface LegacyProxyEntrySource extends PromotedWidgetSource {\n  disambiguatingSourceNodeId?: NodeId\n}\n\nconst LEGACY_PROXY_WIDGET_PREFIX_PATTERN = /^\\s*(\\d+)\\s*:\\s*(.+)$/\n\ninterface StrippedPrefix {\n  sourceWidgetName: string\n  deepestPrefixId?: NodeId\n}\n\nfunction stripLegacyPrefixes(sourceWidgetName: string): StrippedPrefix {\n  let remaining = sourceWidgetName\n  let deepestPrefixId: NodeId | undefined\n  for (;;) {\n    const match = LEGACY_PROXY_WIDGET_PREFIX_PATTERN.exec(remaining)\n    if (!match) return { sourceWidgetName: remaining, deepestPrefixId }\n    deepestPrefixId = toNodeId(match[1])\n    remaining = match[2]\n  }\n}\n\nfunction canResolveLegacyProxy(\n  hostNode: SubgraphNode,\n  sourceNodeId: SerializedNodeId,\n  widgetName: string\n): boolean {\n  return (\n    resolveConcretePromotedWidget(hostNode, sourceNodeId, widgetName).status ===\n    'resolved'\n  )\n}\n\nexport function normalizeLegacyProxyWidgetEntry(\n  hostNode: SubgraphNode,\n  sourceNodeId: SerializedNodeId,\n  sourceWidgetName: string,\n  disambiguatingSourceNodeId?: SerializedNodeId\n): LegacyProxyEntrySource {\n  const normalizedSourceNodeId = toNodeId(sourceNodeId)\n  const normalizedDisambiguatingSourceNodeId =\n    disambiguatingSourceNodeId === undefined\n      ? undefined\n      : toNodeId(disambiguatingSourceNodeId)\n\n  if (canResolveLegacyProxy(hostNode, sourceNodeId, sourceWidgetName)) {\n    return {\n      sourceNodeId: normalizedSourceNodeId,\n      sourceWidgetName,\n      ...(normalizedDisambiguatingSourceNodeId && {\n        disambiguatingSourceNodeId: normalizedDisambiguatingSourceNodeId\n      })\n    }\n  }\n\n  const stripped = stripLegacyPrefixes(sourceWidgetName)\n  const patchDisambiguatingSourceNodeId =\n    stripped.deepestPrefixId ?? normalizedDisambiguatingSourceNodeId\n\n  return {\n    sourceNodeId: normalizedSourceNodeId,\n    sourceWidgetName: stripped.sourceWidgetName,\n    ...(patchDisambiguatingSourceNodeId && {\n      disambiguatingSourceNodeId: patchDisambiguatingSourceNodeId\n    })\n  }\n}\n\nfunction resolveSourceWidget(\n  sourceNode: LGraphNode,\n  sourceWidgetName: string,\n  disambiguatingSourceNodeId?: string\n): IBaseWidget | undefined {\n  if (sourceNode.isSubgraphNode()) {\n    const input = sourceNode.inputs.find((input) => {\n      const target = resolveSubgraphInputTarget(sourceNode, input.name)\n      if (disambiguatingSourceNodeId) {\n        return (\n          target?.widgetName === sourceWidgetName &&\n          target.nodeId === disambiguatingSourceNodeId\n        )\n      }\n      if (input.name === sourceWidgetName) return true\n      return target?.widgetName === sourceWidgetName\n    })\n    // Store-backed projection for a promoted input on a nested subgraph node:\n    // getSlotFromWidget locates the backing slot by widgetId.\n    if (input?.widgetId) return promotedInputWidget(input) ?? undefined\n  }\n\n  const widgets = sourceNode.widgets\n  return (\n    widgets?.find((w) => w.name === sourceWidgetName) ??\n    getPromotableWidgets(sourceNode).find((w) => w.name === sourceWidgetName)\n  )\n}\n\ninterface FlushArgs {\n  hostNode: SubgraphNode\n  hostWidgetValues?: readonly unknown[]\n}\n\ninterface PrimitiveBypassTargetRef {\n  targetNodeId: NodeId\n  targetSlot: number\n}\n\ntype Plan =\n  | { kind: 'alreadyLinked'; subgraphInputName: string }\n  | { kind: 'createSubgraphInput'; sourceWidgetName: string }\n  | {\n      kind: 'primitiveBypass'\n      primitiveNodeId: NodeId\n      sourceWidgetName: string\n      targets: readonly PrimitiveBypassTargetRef[]\n    }\n  | { kind: 'previewExposure'; sourcePreviewName: string }\n  | { kind: 'quarantine'; reason: ProxyWidgetQuarantineReason }\n\ninterface PendingEntry {\n  originalEntry: SerializedProxyWidgetTuple\n  normalized: LegacyProxyEntrySource\n  hostValue: TWidgetValue | undefined\n  isHole: boolean\n  plan: Plan\n}\n\nconst PRIMITIVE_NODE_TYPE = 'PrimitiveNode'\nconst QUARANTINE_PROPERTY = 'proxyWidgetErrorQuarantine'\nconst QUARANTINE_VERSION = 1\nconst PROXY_BYPASS_MARKER_PROPERTY = 'proxyBypassedToSubgraphInput'\n\nexport function flushProxyWidgetMigration(args: FlushArgs): void {\n  const { hostNode, hostWidgetValues } = args\n\n  const tuples = parseProxyWidgets(hostNode.properties.proxyWidgets)\n  if (tuples.length === 0) return\n\n  const normalizedEntries = tuples.map((originalEntry) => {\n    const [sourceNodeId, sourceWidgetName, disambiguator] = originalEntry\n    return {\n      originalEntry,\n      normalized: normalizeLegacyProxyWidgetEntry(\n        hostNode,\n        sourceNodeId,\n        sourceWidgetName,\n        disambiguator\n      )\n    }\n  })\n  const cohort = normalizedEntries.map((entry) => entry.normalized)\n\n  const pending: PendingEntry[] = normalizedEntries.map((entry, index) => {\n    const { value, isHole } = pickHostValue(hostWidgetValues, index)\n    return {\n      ...entry,\n      hostValue: value,\n      isHole,\n      plan: classify(hostNode, entry.normalized, cohort)\n    }\n  })\n\n  const previewStore = usePreviewExposureStore()\n  const quarantineToAppend: ProxyWidgetErrorQuarantineEntry[] = []\n  const primitiveCohorts = new Map<NodeId, PendingEntry[]>()\n\n  for (const entry of pending) {\n    switch (entry.plan.kind) {\n      case 'primitiveBypass': {\n        const c = primitiveCohorts.get(entry.plan.primitiveNodeId) ?? []\n        c.push(entry)\n        primitiveCohorts.set(entry.plan.primitiveNodeId, c)\n        break\n      }\n      case 'alreadyLinked': {\n        const r = repairAlreadyLinked(\n          hostNode,\n          entry,\n          entry.plan.subgraphInputName\n        )\n        if (!r.ok) quarantineToAppend.push(quarantineFor(entry, r.reason))\n        break\n      }\n      case 'createSubgraphInput': {\n        const r = repairCreateSubgraphInput(\n          hostNode,\n          entry,\n          entry.plan.sourceWidgetName\n        )\n        if (!r.ok) quarantineToAppend.push(quarantineFor(entry, r.reason))\n        break\n      }\n      case 'previewExposure': {\n        const r = migratePreview(hostNode, entry, previewStore, entry.plan)\n        if (!r.ok) quarantineToAppend.push(quarantineFor(entry, r.reason))\n        break\n      }\n      case 'quarantine':\n        quarantineToAppend.push(quarantineFor(entry, entry.plan.reason))\n        break\n    }\n  }\n\n  for (const c of primitiveCohorts.values()) {\n    const r = repairPrimitive(hostNode, c)\n    if (!r.ok)\n      for (const e of c) quarantineToAppend.push(quarantineFor(e, r.reason))\n  }\n\n  if (quarantineToAppend.length > 0) {\n    appendQuarantine(hostNode, quarantineToAppend)\n  }\n\n  delete hostNode.properties.proxyWidgets\n}\n\nfunction pickHostValue(\n  hostWidgetValues: readonly unknown[] | undefined,\n  index: number\n): { value: TWidgetValue | undefined; isHole: boolean } {\n  if (\n    hostWidgetValues === undefined ||\n    index < 0 ||\n    index >= hostWidgetValues.length ||\n    !Object.hasOwn(hostWidgetValues, index)\n  ) {\n    return { value: undefined, isHole: true }\n  }\n  const raw = hostWidgetValues[index]\n  if (!isWidgetValue(raw)) return { value: undefined, isHole: true }\n  return { value: raw, isHole: false }\n}\n\nfunction primitiveOutputTopologies(primitiveNode: LGraphNode): LinkTopology[] {\n  if (!primitiveNode.graph) return []\n  return [\n    ...useLinkStore().getOutputSlotLinks(\n      graphScopeOf(primitiveNode.graph),\n      primitiveNode.id,\n      0\n    )\n  ]\n}\n\nfunction collectTargetsStrict(\n  hostNode: SubgraphNode,\n  primitiveNode: LGraphNode\n): PrimitiveBypassTargetRef[] | undefined {\n  const subgraph = hostNode.subgraph\n  const targets: PrimitiveBypassTargetRef[] = []\n  for (const topology of primitiveOutputTopologies(primitiveNode)) {\n    if (!subgraph.links.get(topology.id)) return undefined\n    targets.push({\n      targetNodeId: topology.targetNodeId,\n      targetSlot: topology.targetSlot\n    })\n  }\n  return targets\n}\n\nfunction collectTargetsSkippingDangling(\n  hostNode: SubgraphNode,\n  primitiveNode: LGraphNode\n): PrimitiveBypassTargetRef[] {\n  const subgraph = hostNode.subgraph\n  return primitiveOutputTopologies(primitiveNode)\n    .filter((topology) => subgraph.links.get(topology.id))\n    .map((topology) => ({\n      targetNodeId: topology.targetNodeId,\n      targetSlot: topology.targetSlot\n    }))\n}\n\nfunction cohortDuplicatesPrimitive(\n  cohort: readonly LegacyProxyEntrySource[],\n  primitiveNodeId: NodeId\n): boolean {\n  return (\n    cohort.filter((entry) => entry.sourceNodeId === primitiveNodeId).length >= 2\n  )\n}\n\nfunction classify(\n  hostNode: SubgraphNode,\n  normalized: LegacyProxyEntrySource,\n  cohort: readonly LegacyProxyEntrySource[]\n): Plan {\n  const linkedInput = findHostInputForPromotion(\n    hostNode,\n    normalized.sourceNodeId,\n    normalized.sourceWidgetName\n  )\n  if (linkedInput) {\n    return { kind: 'alreadyLinked', subgraphInputName: linkedInput.name }\n  }\n\n  const sourceNode = hostNode.subgraph.getNodeById(normalized.sourceNodeId)\n  if (!sourceNode) {\n    return { kind: 'quarantine', reason: 'missingSourceNode' }\n  }\n\n  if (sourceNode.type === PRIMITIVE_NODE_TYPE) {\n    const bypassedTo = sourceNode.properties[PROXY_BYPASS_MARKER_PROPERTY]\n    if (typeof bypassedTo === 'string') {\n      const existingInput = hostNode.inputs.find(\n        (input) => input.name === bypassedTo\n      )\n      if (existingInput) {\n        return { kind: 'alreadyLinked', subgraphInputName: existingInput.name }\n      }\n    }\n\n    const targets = collectTargetsSkippingDangling(hostNode, sourceNode)\n    const cohortDuplicated = cohortDuplicatesPrimitive(\n      cohort,\n      normalized.sourceNodeId\n    )\n    if (targets.length >= 1 || cohortDuplicated) {\n      return {\n        kind: 'primitiveBypass',\n        primitiveNodeId: sourceNode.id,\n        sourceWidgetName: normalized.sourceWidgetName,\n        targets\n      }\n    }\n    return { kind: 'quarantine', reason: 'unlinkedSourceWidget' }\n  }\n\n  const sourceWidget = resolveSourceWidget(\n    sourceNode,\n    normalized.sourceWidgetName,\n    normalized.disambiguatingSourceNodeId\n  )\n  if (!sourceWidget) {\n    return { kind: 'quarantine', reason: 'missingSourceWidget' }\n  }\n\n  if (\n    normalized.sourceWidgetName.startsWith('$$') ||\n    isPreviewPseudoWidget(sourceWidget)\n  ) {\n    return {\n      kind: 'previewExposure',\n      sourcePreviewName: normalized.sourceWidgetName\n    }\n  }\n\n  return {\n    kind: 'createSubgraphInput',\n    sourceWidgetName: normalized.sourceWidgetName\n  }\n}\n\nfunction applyHostValueToInput(\n  input: INodeInputSlot,\n  entry: PendingEntry\n): boolean {\n  if (!input.widgetId || entry.isHole) return Boolean(input.widgetId)\n  return useWidgetValueStore().setValue(input.widgetId, entry.hostValue)\n}\n\nfunction applyHostLabelToInput(\n  input: INodeInputSlot,\n  label: string | undefined\n): void {\n  if (label === undefined) return\n  input.label = label\n  if (!input.widgetId) return\n  const state = useWidgetValueStore().getWidget(input.widgetId)\n  if (state) state.label = label\n}\n\nfunction addUniqueSubgraphInput(\n  subgraph: Subgraph,\n  baseName: string,\n  type: string\n): SubgraphInput {\n  const existingNames = subgraph.inputs.map((input) => input.name)\n  const uniqueName = nextUniqueName(baseName, existingNames)\n  return subgraph.addInput(uniqueName, type)\n}\n\ntype Outcome<TOk, TReason = ProxyWidgetQuarantineReason> =\n  | ({ ok: true } & TOk)\n  | { ok: false; reason: TReason }\n\ntype RepairValueResult = Outcome<{ subgraphInputName: string }>\n\nfunction repairAlreadyLinked(\n  hostNode: SubgraphNode,\n  entry: PendingEntry,\n  subgraphInputName: string\n): RepairValueResult {\n  // Resolve by name directly: source-id matching would miss for primitive\n  // bypasses, where the view's `sourceNodeId` is the consumer, not the\n  // primitive.\n  const matches = hostNode.inputs.filter(\n    (input) => input.name === subgraphInputName\n  )\n  if (matches.length === 0) {\n    return { ok: false, reason: 'missingSubgraphInput' }\n  }\n  if (matches.length > 1) {\n    return { ok: false, reason: 'ambiguousSubgraphInput' }\n  }\n  const hostInput = matches[0]\n  if (!applyHostValueToInput(hostInput, entry)) {\n    return { ok: false, reason: 'missingSubgraphInput' }\n  }\n  return { ok: true, subgraphInputName: hostInput.name }\n}\n\nfunction repairCreateSubgraphInput(\n  hostNode: SubgraphNode,\n  entry: PendingEntry,\n  sourceWidgetName: string\n): RepairValueResult {\n  const subgraph = hostNode.subgraph\n  const sourceNode: LGraphNode | null = subgraph.getNodeById(\n    entry.normalized.sourceNodeId\n  )\n  if (!sourceNode) {\n    return { ok: false, reason: 'missingSourceNode' }\n  }\n\n  const sourceWidget = resolveSourceWidget(\n    sourceNode,\n    sourceWidgetName,\n    entry.normalized.disambiguatingSourceNodeId\n  )\n  if (!sourceWidget) {\n    return { ok: false, reason: 'missingSourceWidget' }\n  }\n\n  const slot: INodeInputSlot | undefined =\n    sourceNode.getSlotFromWidget(sourceWidget)\n  if (!slot) {\n    console.warn(\n      '[proxyWidgetMigration] source widget has no backing input slot; quarantining',\n      {\n        sourceNodeId: entry.normalized.sourceNodeId,\n        sourceWidgetName\n      }\n    )\n    return { ok: false, reason: 'missingSubgraphInput' }\n  }\n\n  // oxlint-disable-next-line typescript/no-unnecessary-condition -- legacy workflow slots may omit type at runtime\n  const slotType = String(slot.type ?? '*')\n  const newSubgraphInput = addUniqueSubgraphInput(\n    subgraph,\n    sourceWidgetName,\n    slotType\n  )\n  if (slot.label !== undefined) newSubgraphInput.label = slot.label\n  const link = newSubgraphInput.connect(slot, sourceNode)\n  if (!link) {\n    subgraph.removeInput(newSubgraphInput)\n    return { ok: false, reason: 'missingSubgraphInput' }\n  }\n\n  const hostInput = hostNode.inputs.find(\n    (input) => input.name === newSubgraphInput.name\n  )\n  if (hostInput) {\n    applyHostLabelToInput(hostInput, slot.label)\n    applyHostValueToInput(hostInput, entry)\n  }\n  return { ok: true, subgraphInputName: newSubgraphInput.name }\n}\n\ntype RepairPrimitiveResult = Outcome<\n  { subgraphInputName: string; reconnectCount: number },\n  'primitiveBypassFailed'\n>\n\nconst PRIMITIVE_FAILED: RepairPrimitiveResult = {\n  ok: false,\n  reason: 'primitiveBypassFailed'\n}\n\ninterface SnapshotLink extends PrimitiveBypassTargetRef {\n  primitiveSlot: number\n}\n\ninterface CohortValidationOk {\n  ok: true\n  primitiveNodeId: NodeId\n  sourceWidgetName: string\n  uniqueEntries: readonly PendingEntry[]\n}\n\nfunction failPrimitive(message: string, ctx?: unknown): RepairPrimitiveResult {\n  console.warn(`[proxyWidgetMigration] ${message}`, ctx)\n  return PRIMITIVE_FAILED\n}\n\nfunction userRenamedTitle(primitiveNode: LGraphNode): string | undefined {\n  const title = primitiveNode.title\n  return title && title !== PRIMITIVE_NODE_TYPE ? title : undefined\n}\n\nfunction validateCohort(\n  cohort: readonly PendingEntry[]\n): CohortValidationOk | { ok: false } {\n  const first = cohort.at(0)\n  if (!first || first.plan.kind !== 'primitiveBypass') return { ok: false }\n  const { primitiveNodeId, sourceWidgetName } = first.plan\n  for (const entry of cohort) {\n    if (\n      entry.plan.kind !== 'primitiveBypass' ||\n      entry.plan.primitiveNodeId !== primitiveNodeId ||\n      entry.plan.sourceWidgetName !== sourceWidgetName\n    ) {\n      return { ok: false }\n    }\n  }\n  const uniqueEntries: PendingEntry[] = []\n  for (const entry of cohort) {\n    if (!uniqueEntries.some((k) => isEqual(k.normalized, entry.normalized))) {\n      uniqueEntries.push(entry)\n    }\n  }\n  return { ok: true, primitiveNodeId, sourceWidgetName, uniqueEntries }\n}\n\nfunction rollback(\n  hostNode: SubgraphNode,\n  primitiveNode: LGraphNode,\n  newSubgraphInput: SubgraphInput | undefined,\n  snapshot: readonly SnapshotLink[]\n): void {\n  if (newSubgraphInput) {\n    try {\n      hostNode.subgraph.removeInput(newSubgraphInput)\n    } catch (e) {\n      console.warn('[proxyWidgetMigration] rollback removeInput failed', e)\n    }\n  }\n  for (const link of snapshot) {\n    const targetNode = hostNode.subgraph.getNodeById(link.targetNodeId)\n    if (!targetNode) continue\n    primitiveNode.connect(link.primitiveSlot, targetNode, link.targetSlot)\n  }\n}\n\nfunction repairPrimitive(\n  hostNode: SubgraphNode,\n  cohort: readonly PendingEntry[]\n): RepairPrimitiveResult {\n  const validated = validateCohort(cohort)\n  if (!validated.ok)\n    return failPrimitive('cohort validation failed', { cohort })\n\n  const subgraph = hostNode.subgraph\n  const primitiveNode = subgraph.getNodeById(validated.primitiveNodeId)\n  if (!primitiveNode) return failPrimitive('primitive node missing', validated)\n  if (primitiveNode.type !== PRIMITIVE_NODE_TYPE) {\n    return failPrimitive('node is not a PrimitiveNode', primitiveNode.type)\n  }\n\n  const targets = collectTargetsStrict(hostNode, primitiveNode)\n  if (!targets?.length)\n    return failPrimitive('no targets to reconnect', validated)\n\n  const primitiveOutput = primitiveNode.outputs.at(0)\n  if (!primitiveOutput) return failPrimitive('primitive has no output')\n  // oxlint-disable-next-line typescript/no-unnecessary-condition -- legacy workflow slots may omit type at runtime\n  const primitiveOutputType = String(primitiveOutput.type ?? '*')\n\n  for (const target of targets) {\n    const targetNode = subgraph.getNodeById(target.targetNodeId)\n    if (!targetNode) return failPrimitive('target node missing', target)\n    const targetSlot = targetNode.inputs.at(target.targetSlot)\n    if (!targetSlot) return failPrimitive('target slot missing', target)\n    // oxlint-disable-next-line typescript/no-unnecessary-condition -- legacy workflow slots may omit type at runtime\n    const targetType = String(targetSlot.type ?? '*')\n    if (\n      targetType !== primitiveOutputType &&\n      targetType !== '*' &&\n      primitiveOutputType !== '*'\n    ) {\n      return failPrimitive('target slot type incompatible', {\n        target,\n        targetType,\n        primitiveOutputType\n      })\n    }\n  }\n\n  const baseName = userRenamedTitle(primitiveNode) ?? validated.sourceWidgetName\n  const snapshot: SnapshotLink[] = primitiveOutputTopologies(primitiveNode).map(\n    (topology) => ({\n      primitiveSlot: topology.originSlot,\n      targetNodeId: topology.targetNodeId,\n      targetSlot: topology.targetSlot\n    })\n  )\n\n  let newSubgraphInput: SubgraphInput | undefined\n  try {\n    newSubgraphInput = addUniqueSubgraphInput(\n      subgraph,\n      baseName,\n      primitiveOutputType\n    )\n\n    for (const snap of snapshot) {\n      const targetNode = subgraph.getNodeById(snap.targetNodeId)\n      if (!targetNode)\n        throw new Error(\n          `target node ${snap.targetNodeId} disappeared mid-mutation`\n        )\n      targetNode.disconnectInput(snap.targetSlot, false)\n    }\n\n    for (const target of targets) {\n      const targetNode = subgraph.getNodeById(target.targetNodeId)\n      if (!targetNode)\n        throw new Error(`target node ${target.targetNodeId} disappeared`)\n      const targetSlot = targetNode.inputs.at(target.targetSlot)\n      if (!targetSlot)\n        throw new Error(`target slot ${target.targetSlot} disappeared`)\n      const link = newSubgraphInput.connect(targetSlot, targetNode)\n      if (!link) {\n        throw new Error('SubgraphInput.connect returned no link')\n      }\n    }\n  } catch (e) {\n    rollback(hostNode, primitiveNode, newSubgraphInput, snapshot)\n    return failPrimitive('mutation failed; rolled back', { error: e })\n  }\n\n  const hostInput = hostNode.inputs.find(\n    (input) => input.name === newSubgraphInput.name\n  )\n  if (hostInput) {\n    const valueEntry = validated.uniqueEntries.find((e) => !e.isHole)\n    if (valueEntry) {\n      applyHostValueToInput(hostInput, valueEntry)\n    } else {\n      const primitiveValue = primitiveNode.widgets?.find(\n        (w) => w.name === validated.sourceWidgetName\n      )?.value\n      if (primitiveValue !== undefined) {\n        applyHostValueToInput(hostInput, {\n          ...validated.uniqueEntries[0],\n          hostValue: primitiveValue,\n          isHole: false\n        })\n      }\n    }\n  }\n\n  primitiveNode.properties[PROXY_BYPASS_MARKER_PROPERTY] = newSubgraphInput.name\n\n  return {\n    ok: true,\n    subgraphInputName: newSubgraphInput.name,\n    reconnectCount: targets.length\n  }\n}\n\ntype MigratePreviewResult = Outcome<\n  { previewName: string },\n  'missingSourceNode' | 'missingSourceWidget'\n>\n\nfunction migratePreview(\n  hostNode: SubgraphNode,\n  entry: PendingEntry,\n  store: ReturnType<typeof usePreviewExposureStore>,\n  plan: { kind: 'previewExposure'; sourcePreviewName: string }\n): MigratePreviewResult {\n  const sourceNode = hostNode.subgraph.getNodeById(\n    entry.normalized.sourceNodeId\n  )\n  if (!sourceNode) {\n    return { ok: false, reason: 'missingSourceNode' }\n  }\n\n  const isCanonicalPseudo = plan.sourcePreviewName.startsWith('$$')\n  if (!isCanonicalPseudo) {\n    const widget = sourceNode.widgets?.find(\n      (w) => w.name === plan.sourcePreviewName\n    )\n    if (!widget) {\n      return { ok: false, reason: 'missingSourceWidget' }\n    }\n  }\n\n  const hostNodeLocator = getPreviewExposureHostLocator(hostNode)\n  if (!hostNodeLocator) return { ok: false, reason: 'missingSourceNode' }\n  const existing = store\n    .getExposures(hostNode.rootGraph.id, hostNodeLocator)\n    .find(\n      (exposure) =>\n        exposure.sourceNodeId === entry.normalized.sourceNodeId &&\n        exposure.sourcePreviewName === plan.sourcePreviewName\n    )\n  if (existing) return { ok: true, previewName: existing.name }\n\n  const added = store.addExposure(hostNode.rootGraph.id, hostNodeLocator, {\n    sourceNodeId: entry.normalized.sourceNodeId,\n    sourcePreviewName: plan.sourcePreviewName\n  })\n\n  return { ok: true, previewName: added.name }\n}\n\nfunction quarantineFor(\n  entry: PendingEntry,\n  reason: ProxyWidgetQuarantineReason\n): ProxyWidgetErrorQuarantineEntry {\n  return makeQuarantineEntry({\n    originalEntry: entry.originalEntry,\n    reason,\n    hostValue: entry.isHole ? undefined : entry.hostValue\n  })\n}\n\nexport function appendQuarantine(\n  hostNode: SubgraphNode,\n  entries: readonly ProxyWidgetErrorQuarantineEntry[]\n): void {\n  if (entries.length === 0) return\n\n  for (const {\n    originalEntry: [sourceNodeId, inputName],\n    hostValue\n  } of entries) {\n    if (sourceNodeId !== '-1' || hostValue === undefined) continue\n\n    const input = hostNode.inputs.find((input) => input.name === inputName)\n    if (input?.widgetId)\n      useWidgetValueStore().setValue(input.widgetId, hostValue)\n  }\n\n  const existing = parseProxyWidgetErrorQuarantine(\n    hostNode.properties[QUARANTINE_PROPERTY]\n  )\n  const merged = [...existing]\n  for (const candidate of entries) {\n    if (\n      !merged.some((e) => isEqual(e.originalEntry, candidate.originalEntry))\n    ) {\n      merged.push(candidate)\n    }\n  }\n  if (merged.length === 0) delete hostNode.properties[QUARANTINE_PROPERTY]\n  else hostNode.properties[QUARANTINE_PROPERTY] = merged\n}\n\nexport function readHostQuarantine(\n  hostNode: SubgraphNode\n): ProxyWidgetErrorQuarantineEntry[] {\n  return parseProxyWidgetErrorQuarantine(\n    hostNode.properties[QUARANTINE_PROPERTY]\n  )\n}\n\nexport function makeQuarantineEntry(args: {\n  originalEntry: SerializedProxyWidgetTuple\n  reason: ProxyWidgetQuarantineReason\n  hostValue?: TWidgetValue\n}): ProxyWidgetErrorQuarantineEntry {\n  const entry: ProxyWidgetErrorQuarantineEntry = {\n    originalEntry: args.originalEntry,\n    reason: args.reason,\n    attemptedAtVersion: QUARANTINE_VERSION\n  }\n  if (args.hostValue !== undefined) {\n    entry.hostValue = args.hostValue\n  }\n  return entry\n}\n","import type { ErrorEvent, EventHint } from '@sentry/vue'\n\nimport { isThirdPartyErrorNoise } from '@comfyorg/shared-frontend-utils/telemetry'\n\nimport { isAbortError } from '@/utils/typeGuardUtil'\n\nfunction messageFrom(value: unknown): string | undefined {\n  try {\n    if (typeof value === 'string') return value\n    if (\n      typeof value === 'object' &&\n      value !== null &&\n      'message' in value &&\n      typeof value.message === 'string'\n    )\n      return value.message\n    return undefined\n  } catch {\n    return undefined\n  }\n}\n\nfunction exceptionValueFrom(value: unknown): string[] {\n  try {\n    if (typeof value !== 'object' || value === null || !('value' in value))\n      return []\n    return typeof value.value === 'string' ? [value.value] : []\n  } catch {\n    return []\n  }\n}\n\nfunction exceptionTypeFrom(value: unknown): unknown {\n  try {\n    return typeof value === 'object' && value !== null && 'type' in value\n      ? value.type\n      : undefined\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * Drops a browser-extension messaging failure that the app never emits, and\n * events whose thrown error is an AbortError. That also drops timeouts\n * implemented as a bare `controller.abort()`; the noise reduction is worth it.\n * Chained causes are ignored so a first-party error wrapping one is kept.\n */\nexport function sentryThirdPartyErrorFilter(\n  event: ErrorEvent,\n  hint: EventHint\n): ErrorEvent | null {\n  try {\n    if (\n      isAbortError(hint.originalException) ||\n      exceptionTypeFrom(event.exception?.values?.at(-1)) === 'AbortError'\n    )\n      return null\n    if (\n      isThirdPartyErrorNoise(messageFrom(hint.originalException)) ||\n      isThirdPartyErrorNoise(event.message)\n    )\n      return null\n    const exceptionMessages =\n      event.exception?.values?.flatMap(exceptionValueFrom) ?? []\n    return exceptionMessages.length > 0 &&\n      exceptionMessages.every(isThirdPartyErrorNoise)\n      ? null\n      : event\n  } catch {\n    return event\n  }\n}\n","import type { ErrorEvent, EventHint } from '@sentry/vue'\n\nconst MAX_SCRIPT_PATHS = 250\n\n// FE-3163: remove after a recurrence identifies the failing asset graph.\nperformance.setResourceTimingBufferSize(1000)\n\nfunction eventMessages(event: ErrorEvent, hint: EventHint): string[] {\n  const messages = [event.message]\n  const originalException = hint.originalException\n  if (originalException instanceof Error)\n    messages.push(originalException.message)\n  if (typeof originalException === 'string') messages.push(originalException)\n  event.exception?.values?.forEach((exception) => {\n    messages.push(exception.value)\n  })\n  return messages.filter((message) => message !== undefined)\n}\n\nfunction isVueDirectiveFailure(event: ErrorEvent, hint: EventHint): boolean {\n  const frames =\n    event.exception?.values?.flatMap(\n      (exception) => exception.stacktrace?.frames ?? []\n    ) ?? []\n  if (frames.some((frame) => frame.function?.includes('withDirectives')))\n    return true\n\n  const hasVueCoreFrame = frames.some((frame) =>\n    frame.filename?.includes('vendor-vue-core')\n  )\n  return (\n    hasVueCoreFrame &&\n    eventMessages(event, hint).some((message) =>\n      message.includes('undefined is not a function')\n    )\n  )\n}\n\nfunction firstPartyScriptPaths(): string[] {\n  try {\n    return performance\n      .getEntriesByType('resource')\n      .map((entry) => new URL(entry.name, window.location.href))\n      .filter(\n        (url) =>\n          url.origin === window.location.origin && url.pathname.endsWith('.js')\n      )\n      .map((url) => url.pathname)\n      .slice(0, MAX_SCRIPT_PATHS)\n  } catch {\n    return []\n  }\n}\n\nexport function addVueDirectiveDiagnostics(\n  event: ErrorEvent,\n  hint: EventHint\n): ErrorEvent {\n  if (!isVueDirectiveFailure(event, hint)) return event\n\n  const scriptPaths = firstPartyScriptPaths()\n  return {\n    ...event,\n    tags: {\n      ...event.tags,\n      diagnostic: 'vue_directive_runtime'\n    },\n    contexts: {\n      ...event.contexts,\n      vue_directive_runtime: {\n        frontend_version: __COMFYUI_FRONTEND_VERSION__,\n        frontend_commit: __COMFYUI_FRONTEND_COMMIT__,\n        loaded_script_count: scriptPaths.length,\n        first_party_script_paths: scriptPaths\n      }\n    }\n  }\n}\n","import type { ErrorEvent, EventHint } from '@sentry/vue'\n\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApiError'\n\nimport { sentryThirdPartyErrorFilter } from './thirdPartyErrorNoise'\nimport { addVueDirectiveDiagnostics } from './vueDirectiveErrorDiagnostics'\n\n/**\n * Groups a `WorkspaceApiError` by what failed rather than where it was\n * caught, so each endpoint and server response gets its own Sentry issue.\n * Errors without an `operation`, such as SDK operation refusals, keep Sentry's\n * default grouping.\n */\nfunction groupWorkspaceApiError(\n  event: ErrorEvent,\n  hint: EventHint\n): ErrorEvent {\n  const error = hint.originalException\n  if (!(error instanceof WorkspaceApiError)) return event\n\n  const status = error.status === undefined ? 'none' : String(error.status)\n  const code = error.code ?? 'none'\n  const { operation } = error\n\n  return {\n    ...event,\n    tags: {\n      ...event.tags,\n      workspace_api_status: status,\n      workspace_api_code: code,\n      ...(operation && { workspace_api_operation: operation })\n    },\n    ...(operation && { fingerprint: [error.name, operation, status, code] })\n  }\n}\n\nexport function sentryBeforeSend(\n  event: ErrorEvent,\n  hint: EventHint\n): ErrorEvent | null {\n  const kept = sentryThirdPartyErrorFilter(event, hint)\n  return (\n    kept && groupWorkspaceApiError(addVueDirectiveDiagnostics(kept, hint), hint)\n  )\n}\n","import type { App } from 'vue'\nimport {\n  browserApiErrorsIntegration,\n  eventFiltersIntegration,\n  init as sentryInit\n} from '@sentry/vue'\nimport type {\n  Breadcrumb,\n  Contexts,\n  ErrorEvent,\n  Event,\n  EventHint,\n  Exception\n} from '@sentry/vue'\n\nimport { sentryBeforeSend } from './sentryBeforeSend'\nimport {\n  REDACTION_SENTINEL,\n  redactTelemetryUrls,\n  redactTelemetryValues\n} from './redactTelemetryUrls'\n\n/** `@sentry/vue` re-exports neither `TransactionEvent` nor `SpanJSON`. */\ntype SentryOptions = NonNullable<Parameters<typeof sentryInit>[0]>\ntype SentryTransactionEvent = Parameters<\n  NonNullable<SentryOptions['beforeSendTransaction']>\n>[0]\ntype SentrySpan = Parameters<NonNullable<SentryOptions['beforeSendSpan']>>[0]\n\nfunction redactSentryEvent(event: ErrorEvent, hint: EventHint) {\n  const filtered = sentryBeforeSend(event, hint)\n  if (!filtered) return null\n  redactSharedSentryEventFields(filtered)\n  for (const exception of filtered.exception?.values ?? []) {\n    redactSentryException(exception)\n  }\n  return filtered\n}\n\n/**\n * `beforeSend` runs on error events only. A sampled transaction carries the\n * same page URL and referrer that `HttpContext` copies onto an error, so it\n * needs the shared pass of its own.\n */\nfunction redactSentryTransaction(event: SentryTransactionEvent) {\n  redactSharedSentryEventFields(event)\n  return event\n}\n\nfunction redactSharedSentryEventFields(event: Event): void {\n  if (event.message) {\n    event.message = redactTelemetryUrls(event.message)\n  }\n  if (event.transaction) {\n    event.transaction = redactTelemetryUrls(event.transaction)\n  }\n  if (event.tags) {\n    event.tags = Object.fromEntries(\n      Object.entries(event.tags).map(([key, value]) => [\n        redactTelemetryUrls(key),\n        typeof value === 'string' ? redactTelemetryUrls(value) : value\n      ])\n    )\n  }\n  event.extra = redactTelemetryValues(event.extra)\n  event.contexts = redactSentryContexts(event.contexts)\n  redactSentryRequest(event)\n}\n\nfunction redactSentryRequest(event: Event): void {\n  const request = event.request\n  if (!request) return\n  if (request.url) request.url = redactTelemetryUrls(request.url)\n  request.data = redactUnknownValue(request.data)\n  request.query_string = redactSentryQueryString(request.query_string)\n  const headers = request.headers ?? {}\n  for (const [key, value] of Object.entries(headers)) {\n    if (key.toLowerCase() === 'referer') {\n      headers[key] = redactTelemetryUrls(value)\n    }\n  }\n}\n\ntype SentryQueryString = NonNullable<Event['request']>['query_string']\n\nfunction redactSentryQueryString(query: SentryQueryString): SentryQueryString {\n  if (typeof query === 'string') return query && REDACTION_SENTINEL\n  if (Array.isArray(query)) {\n    return query.map(([key, value]) => [\n      redactTelemetryUrls(key),\n      value && REDACTION_SENTINEL\n    ])\n  }\n  if (!query) return query\n  return Object.fromEntries(\n    Object.entries(query).map(([key, value]) => [\n      redactTelemetryUrls(key),\n      value && REDACTION_SENTINEL\n    ])\n  )\n}\n\nfunction redactUnknownValue(value: unknown): unknown {\n  return redactTelemetryValues({ value })?.value\n}\n\nfunction redactSentryContexts(contexts: Contexts | undefined): Contexts {\n  return Object.fromEntries(\n    Object.entries(contexts ?? {}).map(([key, context]) => [\n      key,\n      context ? redactTelemetryValues(context) : context\n    ])\n  )\n}\n\nfunction redactSentryBreadcrumb(breadcrumb: Breadcrumb): Breadcrumb {\n  return {\n    ...breadcrumb,\n    message: breadcrumb.message\n      ? redactTelemetryUrls(breadcrumb.message)\n      : breadcrumb.message,\n    data: redactTelemetryValues(breadcrumb.data)\n  }\n}\n\nfunction redactSentrySpan(span: SentrySpan): SentrySpan {\n  if (span.description) {\n    span.description = redactTelemetryUrls(span.description)\n  }\n  redactSpanAttributes(span.data)\n  for (const link of span.links ?? []) {\n    if (link.attributes) redactSpanAttributes(link.attributes)\n  }\n  return span\n}\n\nfunction redactSpanAttributes(attributes: SentrySpan['data']): void {\n  for (const [key, value] of Object.entries(attributes)) {\n    if (typeof value === 'string') {\n      attributes[key] = redactTelemetryUrls(value)\n    } else if (Array.isArray(value)) {\n      attributes[key] = value.map((item) =>\n        typeof item === 'string' ? redactTelemetryUrls(item) : item\n      ) as typeof value\n    }\n  }\n}\n\nfunction redactSentryException(exception: Exception): void {\n  if (exception.type) exception.type = redactTelemetryUrls(exception.type)\n  if (exception.value) exception.value = redactTelemetryUrls(exception.value)\n  for (const frame of exception.stacktrace?.frames ?? []) {\n    if (frame.filename) frame.filename = redactTelemetryUrls(frame.filename)\n    if (frame.abs_path) frame.abs_path = redactTelemetryUrls(frame.abs_path)\n  }\n}\n\nexport function initSentry({\n  app,\n  dsn,\n  enabled,\n  isCloud\n}: {\n  app: App\n  dsn: string\n  enabled: boolean\n  isCloud: boolean\n}) {\n  sentryInit({\n    app,\n    dsn,\n    enabled,\n    release: __COMFYUI_FRONTEND_VERSION__,\n    normalizeDepth: 8,\n    tracesSampleRate: isCloud ? 1.0 : 0,\n    replaysSessionSampleRate: 0,\n    replaysOnErrorSampleRate: 0,\n    beforeSend: redactSentryEvent,\n    beforeSendTransaction: redactSentryTransaction,\n    beforeBreadcrumb: redactSentryBreadcrumb,\n    beforeSendSpan: redactSentrySpan,\n    denyUrls: [/^(?:chrome|moz|safari(?:-web)?|ms-browser)-extension:\\/\\//],\n    // Only set these for non-cloud builds\n    ...(isCloud\n      ? {\n          integrations: [\n            // Disable event target wrapping to reduce overhead on high-frequency\n            // DOM events (pointermove, mousemove, wheel). Sentry still captures\n            // errors via window.onerror and unhandledrejection.\n            browserApiErrorsIntegration({ eventTarget: false })\n          ]\n        }\n      : {\n          integrations: [eventFiltersIntegration()],\n          autoSessionTracking: false,\n          defaultIntegrations: false\n        })\n  })\n}\n","import { getActivePinia } from 'pinia'\n\n/** Gates store-backed telemetry setup until `main.ts` installs Pinia. */\nlet storesReady: Promise<void> = Promise.resolve()\nlet resolveStoresReady: (() => void) | undefined\n\n/** Opens the window during which no Pinia instance is installed yet. */\nexport function markStoresPending(): void {\n  if (resolveStoresReady) return\n  storesReady = new Promise<void>((resolve) => {\n    resolveStoresReady = resolve\n  })\n}\n\n/** Closes the window opened by {@link markStoresPending}. */\nexport function markStoresReady(): void {\n  resolveStoresReady?.()\n  resolveStoresReady = undefined\n  storesReady = Promise.resolve()\n}\n\n/** Resolves once store-backed composables are safe to call. */\nexport function whenStoresReady(): Promise<void> {\n  return getActivePinia() ? Promise.resolve() : storesReady\n}\n","import { watch } from 'vue'\nimport type { Router } from 'vue-router'\n\nimport { t } from '@/i18n'\nimport {\n  clearPreservedQuery,\n  getPreservedQueryParam\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { useDialogService } from '@/services/dialogService'\nimport { useAuthStore } from '@/stores/authStore'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.DESKTOP_LOGIN\nconst DESKTOP_LOGIN_CODE_KEY = 'desktop_login_code'\n\n// The backend issues \"dlc_\" + 43 base64url chars; bounds are loose so the\n// backend stays the authority on exact code length.\nconst DESKTOP_LOGIN_CODE_PATTERN = /^dlc_[A-Za-z0-9_-]{20,256}$/\n\n// Statuses that mean the desktop app must start a fresh sign-in, so the code\n// is dropped. 401 stays transient: the session may still be settling.\nconst TERMINAL_REDEEM_STATUSES = new Set([400, 403, 404, 409, 410])\n\n// One delayed in-page retry, so an approved sign-in always reaches a success\n// or failure toast without ever looping within a page load.\nconst MAX_REDEEM_ATTEMPTS = 2\nconst RETRY_DELAY_MS = 5_000\n\n// Abort the redeem request if the backend hangs; treated as transient.\nconst REDEEM_TIMEOUT_MS = 10_000\n\ninterface CodeRedemptionState {\n  attempts: number\n  approvedUserUid: string | null\n  settled: boolean\n  forceTokenRefresh: boolean\n}\n\n// Keyed by code so a different code arriving later gets its own approval and\n// attempt budget, while retries of the same code reuse both.\nconst codeStates = new Map<string, CodeRedemptionState>()\n\n// Coalesces concurrent triggers into one drain; a trigger arriving mid-drain\n// (e.g. the auth watcher firing while the dialog is open) is replayed as one\n// more pass instead of being dropped.\nlet draining = false\nlet retriggerRequested = false\n\nlet authWatcherInstalled = false\n\nlet activeRouter: Router | null = null\n\nfunction onAuthHandoffRoute(): boolean {\n  return (\n    activeRouter?.currentRoute.value.meta.defersDesktopLoginRedemption === true\n  )\n}\n\nfunction getCodeState(code: string): CodeRedemptionState {\n  const existing = codeStates.get(code)\n  if (existing) return existing\n  const fresh = {\n    attempts: 0,\n    approvedUserUid: null,\n    settled: false,\n    forceTokenRefresh: false\n  }\n  codeStates.set(code, fresh)\n  return fresh\n}\n\n// A newer code can be stashed while an older one is mid-redemption; settling\n// the older one must not wipe it.\nfunction clearStashIfHolds(code: string): void {\n  if (getPreservedQueryParam(NAMESPACE, DESKTOP_LOGIN_CODE_KEY) === code) {\n    clearPreservedQuery(NAMESPACE)\n  }\n}\n\nfunction settle(code: string, state: CodeRedemptionState): void {\n  state.settled = true\n  clearStashIfHolds(code)\n}\n\nfunction handleTransientFailure(\n  code: string,\n  state: CodeRedemptionState,\n  reason: string\n): void {\n  console.warn(`[DesktopLoginRedemption] Redeem request failed: ${reason}`)\n  if (state.attempts < MAX_REDEEM_ATTEMPTS) {\n    // attempts only increments, so this branch runs at most once per code\n    // and cannot stack retry timers.\n    setTimeout(() => {\n      void redeemPendingDesktopLoginCode()\n    }, RETRY_DELAY_MS)\n    return\n  }\n  // Budget spent: drop the code and tell the user instead of failing silently.\n  settle(code, state)\n  useToast().error(t('desktopLogin.failedSummary'), {\n    description: t('desktopLogin.failedDetail'),\n    duration: 6000\n  })\n}\n\n// Explicit approval defeats device-code phishing: a lured click on a leaked\n// link must not bind the victim's session to an attacker's desktop app.\n// Approval is per code *and* account.\nasync function confirmRedemption(\n  state: CodeRedemptionState,\n  uid: string\n): Promise<boolean> {\n  if (state.approvedUserUid === uid) return true\n  const confirmed = await useDialogService().confirm({\n    key: 'global-desktop-login-confirm',\n    title: t('desktopLogin.confirmSummary'),\n    message: t('desktopLogin.confirmMessage')\n  })\n  if (confirmed !== true) return false\n  state.approvedUserUid = uid\n  return true\n}\n\nfunction settledForSsoSession(\n  code: string,\n  state: CodeRedemptionState\n): boolean {\n  const auth = useAuthStore()\n  if (auth.currentUser !== null || !auth.signedInWithSso) return false\n  settle(code, state)\n  useToast().warning(t('desktopLogin.ssoUnavailableSummary'), {\n    description: t('desktopLogin.ssoUnavailableDetail'),\n    duration: 8000\n  })\n  return true\n}\n\nasync function redeemCode(code: string): Promise<void> {\n  const state = getCodeState(code)\n  if (state.settled) {\n    // A later navigation can re-capture an already-settled code; drop it.\n    clearStashIfHolds(code)\n    return\n  }\n\n  if (settledForSsoSession(code, state)) return\n\n  // No session yet (e.g. code captured on the login page): keep the stash and\n  // let a post-login trigger redeem it.\n  const user = useAuthStore().currentUser\n  if (!user) return\n\n  // Mid-handoff the imminent hard reload would destroy an open dialog; keep\n  // the stash and let the reloaded app prompt on a stable route.\n  if (onAuthHandoffRoute()) return\n\n  if (!(await confirmRedemption(state, user.uid))) {\n    // Declined/dismissed: drop the code without an error.\n    settle(code, state)\n    return\n  }\n\n  // Approval binds the code to one account: if the session changed while the\n  // dialog was open, keep the code stashed and let the (replayed) auth-change\n  // trigger re-prompt under the now-current account.\n  const approvedUser = useAuthStore().currentUser\n  if (!approvedUser || approvedUser.uid !== state.approvedUserUid) return\n\n  state.attempts++\n\n  // Token comes straight from the Firebase user: authStore.getIdToken()\n  // surfaces failures through a modal dialog this background flow must avoid.\n  let idToken: string\n  try {\n    idToken = await approvedUser.getIdToken(state.forceTokenRefresh)\n  } catch {\n    handleTransientFailure(code, state, 'could not get id token')\n    return\n  }\n\n  let response: Response\n  try {\n    response = await fetch(api.apiURL('/auth/desktop-login-codes/redeem'), {\n      method: 'POST',\n      headers: {\n        Authorization: `Bearer ${idToken}`,\n        'Content-Type': 'application/json'\n      },\n      // TODO(@comfyorg/ingest-types): type the payload with the generated\n      // request type once the desktop-login-codes openapi addition propagates.\n      body: JSON.stringify({ code }),\n      signal: AbortSignal.timeout(REDEEM_TIMEOUT_MS)\n    })\n  } catch (error) {\n    handleTransientFailure(\n      code,\n      state,\n      error instanceof Error && error.name === 'TimeoutError'\n        ? 'request timed out'\n        : 'network error'\n    )\n    return\n  }\n\n  if (response.ok) {\n    settle(code, state)\n    useToast().success(t('desktopLogin.successSummary'), {\n      description: t('desktopLogin.successDetail'),\n      duration: 4000\n    })\n    return\n  }\n\n  if (TERMINAL_REDEEM_STATUSES.has(response.status)) {\n    settle(code, state)\n    useToast().error(t('desktopLogin.expiredSummary'), {\n      description: t('desktopLogin.expiredDetail'),\n      duration: 6000\n    })\n    return\n  }\n\n  // A 401 usually means a stale cached id token; mint a fresh one on retry.\n  if (response.status === 401) state.forceTokenRefresh = true\n  handleTransientFailure(code, state, `status ${response.status}`)\n}\n\nexport function hasPendingDesktopLoginCode(): boolean {\n  const code = getPreservedQueryParam(NAMESPACE, DESKTOP_LOGIN_CODE_KEY)\n  return code !== undefined && DESKTOP_LOGIN_CODE_PATTERN.test(code)\n}\n\nasync function redeemPendingDesktopLoginCode(): Promise<void> {\n  // Never rejects: the triggers fire-and-forget this.\n  if (draining) {\n    retriggerRequested = true\n    return\n  }\n  draining = true\n  try {\n    do {\n      retriggerRequested = false\n      const code = getPreservedQueryParam(NAMESPACE, DESKTOP_LOGIN_CODE_KEY)\n      if (!code) continue\n      if (!DESKTOP_LOGIN_CODE_PATTERN.test(code)) {\n        clearPreservedQuery(NAMESPACE)\n        continue\n      }\n      await redeemCode(code)\n      if (code !== getPreservedQueryParam(NAMESPACE, DESKTOP_LOGIN_CODE_KEY))\n        retriggerRequested = true\n    } while (retriggerRequested)\n  } catch (error) {\n    console.error('[DesktopLoginRedemption] Redemption failed:', error)\n  } finally {\n    draining = false\n  }\n}\n\nfunction installAuthWatcherOnce(): void {\n  if (authWatcherInstalled) return\n  authWatcherInstalled = true\n  // A session can appear without a navigation (e.g. dialog-based sign-in).\n  // Installed lazily because pinia is not active when router.ts evaluates.\n  watch(\n    () => useAuthStore().currentUser,\n    () => {\n      void redeemPendingDesktopLoginCode()\n    }\n  )\n}\n\n/**\n * Redeems desktop login codes (`?desktop_login_code=dlc_...`).\n *\n * The desktop app opens the browser with an opaque one-time code and polls\n * the cloud backend; redeeming the code from a signed-in browser session,\n * with the user's approval, releases a one-time custom token to that poll\n * and signs the desktop app in. The preserved-query tracker (configured in\n * router.ts) strips the code from the URL at capture time, so the\n * sessionStorage-backed stash is the only place it lives.\n *\n * Routes flagged `meta.defersDesktopLoginRedemption` suppress the prompt:\n * the auth handoff ends in a hard reload that only the stash survives.\n */\nexport function installDesktopLoginRedemption(router: Router): void {\n  activeRouter = router\n  router.afterEach(() => {\n    installAuthWatcherOnce()\n    void redeemPendingDesktopLoginCode()\n  })\n}\n","import type { WebSessionEnd } from '@/platform/auth/session/cloudWebSessionStore'\nimport type { SsoHint } from '@/platform/auth/session/ssoReentryStorage'\n\n/** `failed` is a return from ingest carrying `?sso_error=`. */\nexport type SsoReentryAttempt = 'none' | 'recent' | 'failed'\n\nexport type SsoReentry =\n  | { readonly kind: 'sso-redirect'; readonly email: string }\n  | { readonly kind: 'login-with-sso-open' }\n  | { readonly kind: 'login' }\n\nconst LOGIN: SsoReentry = { kind: 'login' }\nconst LOGIN_WITH_SSO_OPEN: SsoReentry = { kind: 'login-with-sso-open' }\n\n/** Where a tab goes to sign in again; undefined `sessionEnd` means no web session. */\nexport function decideSsoReentry(input: {\n  readonly ssoEnabled: boolean\n  readonly sessionEnd: WebSessionEnd | undefined\n  readonly hint: SsoHint | null\n  readonly attempt: SsoReentryAttempt\n}): SsoReentry {\n  const { ssoEnabled, sessionEnd, hint, attempt } = input\n  if (!ssoEnabled || sessionEnd !== 'lapsed' || attempt === 'failed') {\n    return LOGIN\n  }\n  if (!hint) return LOGIN\n  return attempt === 'none'\n    ? { kind: 'sso-redirect', email: hint.email }\n    : LOGIN_WITH_SSO_OPEN\n}\n","import { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport type { PreservedQueryDefinition } from '@/platform/navigation/preservedQueryTracker'\n\n/**\n * What the router stashes before a navigation drops the query, so a deep link\n * survives the sign-in and onboarding redirects. A namespace that only appears\n * in `PRESERVED_QUERY_NAMESPACES` is never captured: hydrating it later finds\n * an empty stash and the intent is lost, so a loader that hydrates a namespace\n * belongs in this list too.\n */\nexport const PRESERVED_QUERY_DEFINITIONS: PreservedQueryDefinition[] = [\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.TEMPLATE,\n    keys: ['template', 'source', 'mode']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.SHARE,\n    keys: ['share']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.INVITE,\n    keys: ['invite']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.CREATE_WORKSPACE,\n    keys: ['create_workspace']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.OAUTH,\n    keys: ['oauth_request_id']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.PRICING,\n    keys: ['pricing', 'stop', 'cycle'],\n    requiredKey: 'pricing'\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.TOPUP,\n    keys: ['topup']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.SETTINGS,\n    keys: ['settings']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.ASSETS,\n    keys: ['assets']\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.DESKTOP_LOGIN,\n    keys: ['desktop_login_code'],\n    stripAfterCapture: true\n  },\n  {\n    namespace: PRESERVED_QUERY_NAMESPACES.WORKSPACE,\n    keys: ['workspace'],\n    rejectRepeated: true\n  }\n]\n","import type { LocationQuery, Router } from 'vue-router'\n\nimport {\n  capturePreservedQuery,\n  clearPreservedQuery,\n  hydratePreservedQuery\n} from '@/platform/navigation/preservedQueryManager'\n\nexport interface PreservedQueryDefinition {\n  namespace: string\n  keys: string[]\n  requiredKey?: string\n  /**\n   * When set, keys present in the query are removed from the client-side URL\n   * before navigation completes. Later guards, afterEach hooks, and views must\n   * read a strip-marked key from the preserved-query stash instead of\n   * route.query or fullPath. Because the stash is the only carrier after\n   * stripping, captures for the namespace merge into the existing stash and an\n   * explicitly empty value clears the stashed key; non-strip namespaces keep\n   * replace-on-capture semantics.\n   */\n  stripAfterCapture?: boolean\n  /**\n   * When set, a key present as a repeated (array) value, or present with no\n   * value at all (`?key`, which the router reads as `null`, in a single\n   * value or inside an array), is captured as an ambiguous marker instead of\n   * silently picking one: repeated values join with `,`; a lone `null`\n   * becomes a bare `,`. Both are strings outside any real id's charset, so\n   * they read back as invalid rather than resolving to one of several\n   * colliding values or to \"absent\" (`capturePreservedQuery` itself drops a\n   * null/empty value as not worth capturing).\n   */\n  rejectRepeated?: true\n}\n\n/** Marks each `keys` entry present as a repeated value, or with no value at\n * all, with a charset-invalid string capturePreservedQuery would otherwise\n * either mis-simplify (repeated → first entry) or drop (null → nothing).\n * Leaves every other key untouched. */\nfunction withAmbiguityMarked(\n  query: LocationQuery,\n  keys: string[]\n): LocationQuery {\n  const result = { ...query }\n  for (const key of keys) {\n    const value = result[key]\n    const values = Array.isArray(value) ? value : [value]\n    const isRepeated = values.length > 1\n    const hasBareEntry = values.includes(null)\n    if (!isRepeated && !hasBareEntry) continue\n    result[key] = values.map((entry) => entry ?? '').join(',') || ','\n  }\n  return result\n}\n\nexport const installPreservedQueryTracker = (\n  router: Router,\n  definitions: PreservedQueryDefinition[]\n) => {\n  router.beforeEach((to, _from, next) => {\n    const queryKeys = new Set(Object.keys(to.query))\n    const keysToStrip = new Set<string>()\n\n    definitions.forEach(\n      ({ namespace, keys, requiredKey, stripAfterCapture, rejectRepeated }) => {\n        hydratePreservedQuery(namespace)\n        const presentKeys = keys.filter((key) => queryKeys.has(key))\n        if (presentKeys.length === 0) return\n        if (requiredKey && !queryKeys.has(requiredKey)) {\n          clearPreservedQuery(namespace)\n          return\n        }\n        const captureQuery = rejectRepeated\n          ? withAmbiguityMarked(to.query, keys)\n          : to.query\n        capturePreservedQuery(namespace, captureQuery, keys, {\n          merge: stripAfterCapture\n        })\n        if (stripAfterCapture) {\n          presentKeys.forEach((key) => keysToStrip.add(key))\n        }\n      }\n    )\n\n    if (keysToStrip.size === 0) {\n      next()\n      return\n    }\n\n    const cleanedQuery = { ...to.query }\n    keysToStrip.forEach((key) => delete cleanedQuery[key])\n    next({ path: to.path, query: cleanedQuery, hash: to.hash })\n  })\n}\n","import type { RouteLocation, RouteLocationRaw } from 'vue-router'\n\nimport { reportError } from '@/platform/telemetry/reportError'\n\n/**\n * An unmatched path is attacker-supplied and unbounded, so it is truncated\n * before it reaches telemetry. It is not redacted: every route in this app is\n * a static literal with no parameter segments, and OAuth/share state travels\n * in the query string, which `to.path` excludes — so a path segment carries no\n * secret material, and the specific bad URL is the whole diagnostic value.\n */\nconst MAX_REPORTED_PATH_LENGTH = 128\n\n/**\n * Unknown paths redirect to root rather than hanging on the splash screen with\n * no route match. The global auth guard then routes unauthenticated users to\n * /cloud/login as normal.\n *\n * The Error message is deliberately static so every unmatched path groups into\n * one issue; the path itself rides along as context, where high cardinality is\n * cheap and a spike is still attributable.\n */\nexport function unmatchedRouteRedirect(to: RouteLocation): RouteLocationRaw {\n  reportError(new Error('Unmatched route'), {\n    surface: 'platform',\n    errorType: 'unmatched_route',\n    level: 'warning',\n    context: { path: to.path.slice(0, MAX_REPORTED_PATH_LENGTH) }\n  })\n\n  return '/'\n}\n","import { until } from '@vueuse/core'\nimport { delay } from 'es-toolkit'\nimport { storeToRefs } from 'pinia'\nimport {\n  createRouter,\n  createWebHashHistory,\n  createWebHistory\n} from 'vue-router'\nimport type {\n  LocationQueryRaw,\n  NavigationGuardNext,\n  RouteLocationNormalized\n} from 'vue-router'\n\nimport { readSsoError, ssoStartUrl } from '@comfyorg/account-core/sso'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport type { CloudSignIn } from '@/platform/auth/session/cloudIdentityBoot'\nimport { cloudSignIn } from '@/platform/auth/session/cloudIdentityBoot'\nimport { useCloudWebSessionStore } from '@/platform/auth/session/cloudWebSessionStore'\nimport {\n  hasRecentSsoReentry,\n  markSsoReentry,\n  readSsoHint\n} from '@/platform/auth/session/ssoReentryStorage'\nimport { trackSsoRequiredShown } from '@/platform/auth/sso/ssoTelemetry'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useAuthStore } from '@/stores/authStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useUserStore } from '@/stores/userStore'\nimport LayoutDefault from '@/views/layouts/LayoutDefault.vue'\n\nimport { captureOAuthRequestId } from '@/platform/cloud/oauth/oauthState'\nimport { SSO_ENTRY_OPEN_QUERY } from '@/platform/cloud/onboarding/sso/ssoEntryQuery'\nimport { decideSsoReentry } from '@/platform/cloud/onboarding/sso/ssoReentry'\nimport {\n  hasPendingDesktopLoginCode,\n  installDesktopLoginRedemption\n} from '@/platform/cloud/onboarding/desktopLoginRedemption'\nimport { PRESERVED_QUERY_DEFINITIONS } from '@/platform/navigation/preservedQueryDefinitions'\nimport { installPreservedQueryTracker } from '@/platform/navigation/preservedQueryTracker'\nimport { unmatchedRouteRedirect } from '@/platform/navigation/unmatchedRoute'\nimport { preserveLoggedOutShareAuthAttribution } from '@/platform/workflow/sharing/utils/shareAuthAttribution'\n\nconst cloudOnboardingRoutes = isCloud\n  ? (await import('./platform/cloud/onboarding/onboardingCloudRoutes'))\n      .cloudOnboardingRoutes\n  : []\n\nconst isFileProtocol = window.location.protocol === 'file:'\n\n/**\n * Determine base path for the router.\n * - Electron: always root\n * - Cloud: use Vite's BASE_URL (configured at build time)\n * - Standard web (including reverse proxy subpaths): use window.location.pathname\n *   to support deployments like http://mysite.com/ComfyUI/\n */\nfunction getBasePath(): string {\n  if (isDesktop) return '/'\n  if (isCloud) return import.meta.env.BASE_URL || '/'\n  return window.location.pathname\n}\n\nconst basePath = getBasePath()\n\nfunction trackPageView(): void {\n  useTelemetry()?.trackPageView(document.title, {\n    path: window.location.href\n  })\n}\n\nconst router = createRouter({\n  history: isFileProtocol\n    ? createWebHashHistory()\n    : // Base path must be specified to ensure correct relative paths\n      // Example: For URL 'http://localhost:7801/ComfyBackendDirect',\n      // we need this base path or assets will incorrectly resolve from 'http://localhost:7801/'\n      createWebHistory(basePath),\n  routes: [\n    ...(isCloud ? cloudOnboardingRoutes : []),\n    {\n      path: '/',\n      component: LayoutDefault,\n      children: [\n        {\n          path: '',\n          name: 'GraphView',\n          component: () => import('@/views/GraphView.vue'),\n          beforeEnter: async (_to, _from, next) => {\n            // Then check user store\n            const userStore = useUserStore()\n            await userStore.initialize()\n            if (userStore.needsLogin) {\n              next('/user-select')\n            } else {\n              next()\n            }\n          }\n        },\n        {\n          path: 'user-select',\n          name: 'UserSelectView',\n          component: () => import('@/views/UserSelectView.vue')\n        }\n      ]\n    },\n    { path: '/:pathMatch(.*)*', redirect: unmatchedRouteRedirect }\n  ],\n\n  scrollBehavior(_to, _from, savedPosition) {\n    if (savedPosition) {\n      return savedPosition\n    } else {\n      return { top: 0 }\n    }\n  }\n})\n\ninstallPreservedQueryTracker(router, PRESERVED_QUERY_DEFINITIONS)\n\nrouter.beforeEach((to, _from, next) => {\n  captureOAuthRequestId(to.query)\n  next()\n})\n\nrouter.afterEach(() => {\n  trackPageView()\n})\n\nconst PUBLIC_ROUTE_SIGN_IN_TIMEOUT_MS = 3_000\n\nif (isCloud) {\n  const { flags } = useFeatureFlags()\n  const PUBLIC_ROUTE_NAMES = new Set([\n    'cloud-login',\n    'cloud-signup',\n    'cloud-forgot-password',\n    'cloud-oauth-consent',\n    'cloud-sorry-contact-support'\n  ])\n  const PUBLIC_ROUTE_PATHS = new Set([\n    '/cloud/login',\n    '/cloud/signup',\n    '/cloud/forgot-password',\n    '/oauth/consent',\n    '/cloud/sorry-contact-support'\n  ])\n\n  function isPublicRoute(to: RouteLocationNormalized) {\n    const name = String(to.name)\n    if (PUBLIC_ROUTE_NAMES.has(name)) return true\n    const path = to.path\n    return PUBLIC_ROUTE_PATHS.has(path)\n  }\n  async function publicRouteSignIn(): Promise<CloudSignIn> {\n    return Promise.race([\n      cloudSignIn(),\n      delay(PUBLIC_ROUTE_SIGN_IN_TIMEOUT_MS).then(() => 'signed_out' as const)\n    ])\n  }\n  const watchedSessions = new WeakSet<object>()\n  /** Closes the signed-in tab's dialogs and re-runs this guard on the current route, which then sends the tab to sign-in. */\n  function rerouteWhenSignedOutElsewhere(): void {\n    const webSession = useCloudWebSessionStore()\n    if (watchedSessions.has(webSession)) return\n    watchedSessions.add(webSession)\n    webSession.onSignedOutElsewhere(() => {\n      const dialogs = useDialogStore()\n      dialogs.dialogStack\n        .map(({ key }) => key)\n        .forEach((key) => dialogs.closeDialog({ key }))\n      const { path, query, hash } = router.currentRoute.value\n      void router.replace({ path, query, hash, force: true })\n    })\n  }\n  /** A lapsed SSO session goes back through its identity provider, once per tab per window. */\n  function sendToSignIn(\n    to: RouteLocationNormalized,\n    query: LocationQueryRaw,\n    next: NavigationGuardNext\n  ): void {\n    const ssoError = flags.ssoEnabled\n      ? readSsoError(to.query.sso_error)\n      : undefined\n    const reentry = decideSsoReentry({\n      ssoEnabled: flags.ssoEnabled,\n      sessionEnd: useCloudWebSessionStore().sessionEnd(),\n      hint: readSsoHint(),\n      attempt: ssoError ? 'failed' : hasRecentSsoReentry() ? 'recent' : 'none'\n    })\n    if (reentry.kind === 'sso-redirect' && markSsoReentry()) {\n      trackSsoRequiredShown('cloud_app', 'session_expired', 'redirect')\n      window.location.assign(\n        ssoStartUrl({\n          email: reentry.email,\n          returnTo: to.fullPath,\n          origin: window.location.origin\n        })\n      )\n      return next(false)\n    }\n    next({\n      name: 'cloud-login',\n      query: {\n        ...query,\n        ...(reentry.kind !== 'login' && SSO_ENTRY_OPEN_QUERY),\n        ...(ssoError && { sso_error: ssoError })\n      }\n    })\n  }\n\n  // Global authentication guard\n  router.beforeEach(async (to, _from, next) => {\n    rerouteWhenSignedOutElsewhere()\n    const authStore = useAuthStore()\n\n    // Wait for Firebase auth to initialize\n    // Timeout after 16 seconds\n    if (!authStore.isInitialized) {\n      try {\n        const { isInitialized } = storeToRefs(authStore)\n        await until(isInitialized).toBe(true, { timeout: 16_000 })\n      } catch (error) {\n        console.error('Auth initialization failed:', error)\n        return next({ name: 'cloud-auth-timeout' })\n      }\n    }\n\n    let signIn = isPublicRoute(to)\n      ? await publicRouteSignIn()\n      : await cloudSignIn()\n    if (signIn === 'pending' && !isPublicRoute(to)) {\n      await useCloudWebSessionStore().whenDecided()\n      signIn = await cloudSignIn()\n    }\n    const needsFirebaseForDesktopCode =\n      signIn === 'signed_in' &&\n      authStore.currentUser === null &&\n      !authStore.signedInWithSso &&\n      hasPendingDesktopLoginCode()\n    const isLoggedIn = signIn === 'signed_in' && !needsFirebaseForDesktopCode\n    preserveLoggedOutShareAuthAttribution(to.query, isLoggedIn)\n\n    // Allow public routes\n    if (isPublicRoute(to)) {\n      return next()\n    }\n\n    // Special handling for user-check\n    // These routes need auth but handle their own routing logic\n    if (to.name === 'cloud-user-check') {\n      if (to.meta.requiresAuth && !isLoggedIn) {\n        return next({ name: 'cloud-login' })\n      }\n      return next()\n    }\n\n    // Prevent redirect loop when coming from user-check\n    if (_from.name === 'cloud-user-check' && to.path === '/') {\n      return next()\n    }\n\n    const query = {\n      ...(to.fullPath !== '/' && {\n        previousFullPath: encodeURIComponent(to.fullPath)\n      }),\n      ...(needsFirebaseForDesktopCode && { switchAccount: 'true' })\n    }\n\n    // Check if route requires authentication\n    if (to.meta.requiresAuth && !isLoggedIn) {\n      return sendToSignIn(to, query, next)\n    }\n\n    // Handle other protected routes\n    if (!isLoggedIn) {\n      // For Electron, use dialog\n      if (isDesktop) {\n        const loginSuccess = await useAuthDialogs().showSignInDialog()\n        return loginSuccess ? next() : next(false)\n      }\n\n      return sendToSignIn(to, query, next)\n    }\n\n    // User is logged in - check if they need onboarding (when enabled)\n    // For root path, check actual user status to handle waitlisted users\n    if (!isDesktop && to.path === '/') {\n      if (!flags.onboardingSurveyEnabled) {\n        return next()\n      }\n      // Import auth functions dynamically to avoid circular dependency\n      const { getSurveyCompletedStatus } =\n        await import('@/platform/cloud/onboarding/auth')\n      try {\n        // Check user's actual status\n        const surveyCompleted = await getSurveyCompletedStatus(\n          useAuthStore().userId\n        )\n\n        // Survey is required for all users (when feature flag enabled)\n        if (!surveyCompleted) {\n          return next({ name: 'cloud-survey' })\n        }\n      } catch (error) {\n        console.error('Failed to check user status:', error)\n        // On error, redirect to user-check as fallback\n        return next({ name: 'cloud-user-check' })\n      }\n    }\n\n    // User is logged in and accessing protected route\n    return next()\n  })\n\n  installDesktopLoginRedemption(router)\n}\n\nexport default router\n","import { attachUnifiedRemintInterceptor } from '@/platform/auth/unified/remintRetry'\nimport { setWorkspaceApiAuth } from '@/platform/workspace/api/workspaceApi'\nimport { useAuthStore } from '@/stores/authStore'\n\nexport function installWorkspaceApiAuth(): void {\n  setWorkspaceApiAuth({\n    getWorkspaceAuthHeader: () =>\n      useAuthStore().getWorkspaceAuthHeaderOrThrow(),\n    getFirebaseAuthHeader: () => useAuthStore().getFirebaseAuthHeaderOrThrow(),\n    attachRetryInterceptor: attachUnifiedRemintInterceptor\n  })\n}\n","<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { maximized = false } = defineProps<{ maximized?: boolean }>()\nconst emit = defineEmits<{ toggle: [] }>()\n\nconst { t } = useI18n()\n</script>\n\n<template>\n  <Button\n    :aria-label=\"maximized ? t('g.restoreDialog') : t('g.maximizeDialog')\"\n    size=\"icon\"\n    variant=\"muted-textonly\"\n    @click=\"emit('toggle')\"\n  >\n    <i\n      :class=\"\n        maximized ? 'icon-[lucide--minimize-2]' : 'icon-[lucide--maximize-2]'\n      \"\n    />\n  </Button>\n</template>\n","<!-- The main global dialog to show various things -->\n<template>\n  <template v-for=\"item in dialogStore.dialogStack\" :key=\"item.key\">\n    <Dialog\n      :open=\"item.visible\"\n      @update:open=\"(open) => onRekaOpenChange(item.key, open)\"\n    >\n      <DialogPortal>\n        <DialogOverlay v-reka-z-index />\n        <DialogContent\n          v-reka-z-index\n          v-bind=\"\n            item.dialogComponentProps.useAutomaticLabeling\n              ? {}\n              : { 'aria-labelledby': item.key }\n          \"\n          :size=\"\n            item.dialogComponentProps.headless\n              ? 'fit'\n              : (item.dialogComponentProps.size ?? 'md')\n          \"\n          :surface=\"item.dialogComponentProps.headless ? 'none' : 'card'\"\n          :maximized=\"!!item.dialogComponentProps.maximized\"\n          :data-dialog-key=\"item.key\"\n          @escape-key-down=\"\n            (e) =>\n              item.dialogComponentProps.closable === false && e.preventDefault()\n          \"\n          @pointer-down-outside=\"\n            (e) => onRekaPointerDownOutside(item.dialogComponentProps, e)\n          \"\n          @mousedown=\"() => dialogStore.riseDialog({ key: item.key })\"\n        >\n          <template v-if=\"item.dialogComponentProps.headless\">\n            <component\n              :is=\"item.component\"\n              v-bind=\"item.contentProps\"\n              :maximized=\"item.dialogComponentProps.maximized\"\n            />\n          </template>\n          <template v-else>\n            <DialogHeader\n              :class=\"\n                item.headerComponent &&\n                item.dialogComponentProps.flush &&\n                cn('p-0', hasHeaderActions(item) && 'pr-3')\n              \"\n            >\n              <component\n                :is=\"item.headerComponent\"\n                v-if=\"item.headerComponent\"\n                v-bind=\"item.headerProps\"\n                :id=\"item.key\"\n              />\n              <DialogTitle v-else :id=\"item.key\">\n                {{ item.title || ' ' }}\n              </DialogTitle>\n              <div\n                v-if=\"hasHeaderActions(item)\"\n                class=\"flex items-center gap-1\"\n              >\n                <DialogMaximize\n                  v-if=\"item.dialogComponentProps.maximizable\"\n                  :maximized=\"!!item.dialogComponentProps.maximized\"\n                  @toggle=\"toggleMaximize(item)\"\n                />\n                <DialogClose v-if=\"hasCloseButton(item)\" />\n              </div>\n            </DialogHeader>\n            <div\n              :class=\"\n                cn(\n                  'flex min-h-0 flex-1 flex-col overflow-auto',\n                  !item.dialogComponentProps.flush && 'px-4 py-2'\n                )\n              \"\n            >\n              <component\n                :is=\"item.component\"\n                v-bind=\"item.contentProps\"\n                :maximized=\"item.dialogComponentProps.maximized\"\n              />\n            </div>\n            <DialogFooter\n              v-if=\"item.footerComponent\"\n              :class=\"item.dialogComponentProps.flush && 'p-0'\"\n            >\n              <component :is=\"item.footerComponent\" v-bind=\"item.footerProps\" />\n            </DialogFooter>\n          </template>\n        </DialogContent>\n      </DialogPortal>\n    </Dialog>\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogFooter from '@/components/ui/dialog/DialogFooter.vue'\nimport DialogHeader from '@/components/ui/dialog/DialogHeader.vue'\nimport DialogMaximize from '@/components/ui/dialog/DialogMaximize.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport { onRekaPointerDownOutside } from '@/components/dialog/dialogDismissGuards'\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\nimport type { DialogInstance } from '@/stores/dialogStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst dialogStore = useDialogStore()\n\nfunction onRekaOpenChange(key: string, open: boolean) {\n  if (!open) dialogStore.closeDialog({ key })\n}\n\nfunction hasCloseButton({ dialogComponentProps }: DialogInstance) {\n  return (\n    dialogComponentProps.closable !== false &&\n    dialogComponentProps.showCloseButton !== false\n  )\n}\n\nfunction hasHeaderActions(item: DialogInstance) {\n  return !!item.dialogComponentProps.maximizable || hasCloseButton(item)\n}\n\nfunction toggleMaximize(item: DialogInstance) {\n  item.dialogComponentProps.maximized = !item.dialogComponentProps.maximized\n}\n</script>\n","<template>\n  <div\n    v-if=\"reconnecting\"\n    role=\"status\"\n    class=\"fixed inset-0 z-10000 flex flex-col items-center justify-center gap-4 bg-base-background p-8 text-center\"\n  >\n    <h1 class=\"m-0 text-lg font-semibold text-base-foreground\">\n      {{ $t('auth.webSession.reconnecting.title') }}\n    </h1>\n    <p class=\"m-0 max-w-md text-muted-foreground\">\n      {{ $t('auth.webSession.reconnecting.detail') }}\n    </p>\n    <Button @click=\"retry\">\n      {{ $t('auth.webSession.reconnecting.retry') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCloudWebSessionStore } from '@/platform/auth/session/cloudWebSessionStore'\n\nconst { reconnecting } = storeToRefs(useCloudWebSessionStore())\n\nfunction retry() {\n  window.location.reload()\n}\n</script>\n","type PreloadFileType = 'js' | 'css' | 'font' | 'image' | 'unknown'\n\ninterface PreloadErrorInfo {\n  url: string | null\n  fileType: PreloadFileType\n  chunkName: string | null\n  message: string\n}\n\nconst CSS_PRELOAD_RE = /Unable to preload CSS for (.+)/\nconst JS_DYNAMIC_IMPORT_RE =\n  /Failed to fetch dynamically imported module:\\s*(.+)/\nconst URL_FALLBACK_RE = /https?:\\/\\/[^\\s\"')]+/\n\nconst FONT_EXTENSIONS = new Set(['woff', 'woff2', 'ttf', 'otf', 'eot'])\nconst IMAGE_EXTENSIONS = new Set([\n  'png',\n  'jpg',\n  'jpeg',\n  'gif',\n  'svg',\n  'webp',\n  'avif',\n  'ico'\n])\n\nfunction extractUrl(message: string): string | null {\n  const cssMatch = message.match(CSS_PRELOAD_RE)\n  if (cssMatch) return cssMatch[1].trim()\n\n  const jsMatch = message.match(JS_DYNAMIC_IMPORT_RE)\n  if (jsMatch) return jsMatch[1].trim()\n\n  const fallbackMatch = message.match(URL_FALLBACK_RE)\n  if (fallbackMatch) return fallbackMatch[0]\n\n  return null\n}\n\nfunction detectFileType(url: string): PreloadFileType {\n  const pathname = new URL(url, 'https://cloud.comfy.org').pathname\n  const ext = pathname.split('.').pop()?.toLowerCase()\n  if (!ext) return 'unknown'\n\n  // Strip query params from extension\n  const cleanExt = ext.split('?')[0]\n\n  if (cleanExt === 'js' || cleanExt === 'mjs') return 'js'\n  if (cleanExt === 'css') return 'css'\n  if (FONT_EXTENSIONS.has(cleanExt)) return 'font'\n  if (IMAGE_EXTENSIONS.has(cleanExt)) return 'image'\n  return 'unknown'\n}\n\nfunction extractChunkName(url: string): string | null {\n  const pathname = new URL(url, 'https://cloud.comfy.org').pathname\n  const filename = pathname.split('/').pop()\n  if (!filename) return null\n\n  // Strip extension\n  const nameWithoutExt = filename.replace(/\\.[^.]+$/, '')\n  // Strip hash suffix (e.g. \"vendor-vue-core-abc123\" -> \"vendor-vue-core\")\n  const withoutHash = nameWithoutExt.replace(/-[a-f0-9]{6,}$/, '')\n  return withoutHash || null\n}\n\nexport function parsePreloadError(error: Error): PreloadErrorInfo {\n  const message = error.message || String(error)\n  const url = extractUrl(message)\n\n  return {\n    url,\n    fileType: url ? detectFileType(url) : 'unknown',\n    chunkName: url ? extractChunkName(url) : null,\n    message\n  }\n}\n","import { parsePreloadError } from '@/utils/preloadErrorUtil'\n\nimport { reportError } from './reportError'\n\n/**\n * Whether a failed resource is one we ship, and can therefore act on.\n *\n * The `error` listener in `App.vue` fires for every `<script>` and\n * `<link rel=stylesheet>` on the page, including the ones GTM, Meta and the\n * other marketing tags inject at runtime. Those fail constantly and for one\n * reason: the visitor runs an ad blocker. Reporting them made\n * `Resource load failed: …` the single largest error group on\n * cloud-frontend-prod, and because Sentry groups on this function's frame\n * rather than on the URL, every blocked host landed in ONE issue with our own\n * asset failures — so the group could be neither read nor archived without\n * losing the failures that matter.\n *\n * Same-origin is the line: our JS and CSS are served from the page's origin.\n * A URL we cannot parse is reported rather than dropped, because an unparseable\n * asset URL is itself a bug worth seeing.\n *\n * Accepted loss: `t.comfy.org` (the PostHog proxy) is ours but cross-origin, so\n * its load failures stop being reported here. They are overwhelmingly the same\n * ad blockers, and a real outage of that host shows up as missing PostHog\n * volume, which is the signal that would actually be watched.\n */\nfunction isFirstPartyResource(url: string): boolean {\n  try {\n    return new URL(url, window.location.href).origin === window.location.origin\n  } catch {\n    return true\n  }\n}\n\n/**\n * Asset failures reach a sink only on cloud builds, and `reportError` writes\n * the console line there. Every other distribution logs locally instead, so\n * one failure never produces two console lines or two RUM events.\n *\n * Third-party resources are dropped on every distribution: they are not ours to\n * fix, and the local console line is as much noise as the Sentry event.\n */\nexport function reportResourceLoadError(url: string, tagName: string): void {\n  if (!isFirstPartyResource(url)) return\n\n  if (__DISTRIBUTION__ !== 'cloud') {\n    console.error('[resource:loadError]', { url, tagName })\n    return\n  }\n\n  reportError(new Error(`Resource load failed: ${url}`), {\n    surface: 'platform',\n    errorType: 'resource_load_error',\n    tags: { tag_name: tagName }\n  })\n}\n\nexport function reportPreloadError(error: Error): void {\n  const info = parsePreloadError(error)\n\n  if (__DISTRIBUTION__ !== 'cloud') {\n    console.error('[vite:preloadError]', {\n      url: info.url,\n      fileType: info.fileType,\n      chunkName: info.chunkName,\n      message: info.message\n    })\n    return\n  }\n\n  reportError(error, {\n    surface: 'platform',\n    errorType: 'vite_preload_error',\n    tags: {\n      file_type: info.fileType,\n      chunk_name: info.chunkName ?? undefined\n    },\n    context: {\n      url: info.url,\n      fileType: info.fileType,\n      chunkName: info.chunkName\n    }\n  })\n}\n","import { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\nimport { useCloudNotificationDialog } from '@/platform/cloud/notification/composables/useCloudNotificationDialog'\nimport { useComfyHubPublishDialog } from '@/platform/workflow/sharing/composables/useComfyHubPublishDialog'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\nimport type { ExtensionDialogService } from '@/services/dialogService'\nimport { useDialogService } from '@/services/dialogService'\n\nexport function createExtensionDialogService(): ExtensionDialogService {\n  const { showPublishDialog } = useComfyHubPublishDialog()\n  return {\n    ...useDialogService(),\n    ...useAuthDialogs(),\n    ...useBillingDialogs(),\n    ...useWorkspaceDialogs(),\n    ...useCloudNo